-- STAGING ONLY 486: canonical receipt chain must retain unknown-station Job Card lines instead of rejecting them.
BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-486-owner-document-receipt-contract',0));DO $g$ BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827035000' AND name='485_contain_uid635_one_shot_review') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827035000') OR pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conrelid='public.pdc_jobcard_attachment_source_row_receipts'::regclass AND conname='pdc_jobcard_attachment_source_row_receipts_work_key_check'),true) IS DISTINCT FROM 'CHECK (work_key = ANY (ARRAY[''bus4x4''::text, ''tint''::text, ''hoist''::text, ''fitting''::text, ''fabrication''::text, ''electrical''::text, ''tyre''::text, ''pitInspection''::text, ''PARTS''::text, ''sublet''::text]))' OR pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conrelid='public.pdc_jobcard_attachment_rule_receipts_279'::regclass AND conname='pdc_jobcard_attachment_rule_receipts_279_work_key_check'),true) IS DISTINCT FROM 'CHECK (work_key = ANY (ARRAY[''bus4x4''::text, ''tint''::text, ''hoist''::text, ''fitting''::text, ''fabrication''::text, ''electrical''::text, ''tyre''::text, ''pitInspection''::text, ''PARTS''::text, ''sublet''::text]))' THEN RAISE EXCEPTION 'PDC_486_TARGET_HEAD_OR_CONSTRAINT_MISMATCH' USING errcode='55000';END IF;END $g$;ALTER TABLE public.pdc_jobcard_attachment_source_row_receipts DROP CONSTRAINT pdc_jobcard_attachment_source_row_receipts_work_key_check,ADD CONSTRAINT pdc_jobcard_attachment_source_row_receipts_work_key_check CHECK(work_key=ANY(ARRAY['bus4x4','tint','hoist','fitting','fabrication','electrical','tyre','pitInspection','PARTS','sublet','owner_supplied_document']));ALTER TABLE public.pdc_jobcard_attachment_rule_receipts_279 DROP CONSTRAINT pdc_jobcard_attachment_rule_receipts_279_work_key_check,ADD CONSTRAINT pdc_jobcard_attachment_rule_receipts_279_work_key_check CHECK(work_key=ANY(ARRAY['bus4x4','tint','hoist','fitting','fabrication','electrical','tyre','pitInspection','PARTS','sublet','owner_supplied_document']));CREATE TABLE public.pdc_uid635_receipt_contract_repairs_486(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='uid635-owner-supplied-document-receipt-contract'),failed_uid bigint NOT NULL CHECK(failed_uid=635),failed_stock text NOT NULL CHECK(failed_stock='13000775'),failed_job_card text NOT NULL CHECK(failed_job_card='J139125494'),failure_constraint text NOT NULL CHECK(failure_constraint='pdc_jobcard_attachment_source_row_receipts_work_key_check'),repair_scope text NOT NULL CHECK(repair_scope='allow owner_supplied_document in canonical source-row and bound rule receipts; no new station mapping'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid635_receipt_contract_repairs_486 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid635_receipt_contract_repairs_486 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid635_receipt_contract_repairs_486(action_key,failed_uid,failed_stock,failed_job_card,failure_constraint,repair_scope) VALUES('uid635-owner-supplied-document-receipt-contract',635,'13000775','J139125494','pdc_jobcard_attachment_source_row_receipts_work_key_check','allow owner_supplied_document in canonical source-row and bound rule receipts; no new station mapping');DO $p$ BEGIN IF pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conrelid='public.pdc_jobcard_attachment_source_row_receipts'::regclass AND conname='pdc_jobcard_attachment_source_row_receipts_work_key_check'),true) NOT LIKE '%owner_supplied_document%' OR pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conrelid='public.pdc_jobcard_attachment_rule_receipts_279'::regclass AND conname='pdc_jobcard_attachment_rule_receipts_279_work_key_check'),true) NOT LIKE '%owner_supplied_document%' OR EXISTS(SELECT 1 FROM public.pdc_email_monitor_pilot WHERE enabled OR automatic_rule_application OR automatic_authenticated_jobcards) THEN RAISE EXCEPTION 'PDC_486_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $p$;INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827036000','486_owner_document_receipt_contract',ARRAY['Repair the exact constraint that rejected UID635 after all 22 lines parsed','Allow owner_supplied_document only as an explicit unknown-station receipt work key in both canonical receipt tables','Do not invent station mappings or hours; keep UID635 nonterminal and Inbox-retained pending exact retry','Production untouched and one-shot writer remains contained']);COMMIT;
